import{_ as a,o as i,c as t,a3 as o}from"./chunks/framework.CJlOecQn.js";const f=JSON.parse('{"title":"Help wanted","description":"Things readers need that we could not confirm from an official page yet.","frontmatter":{"title":"Help wanted","description":"Things readers need that we could not confirm from an official page yet."},"headers":[],"relativePath":"help-wanted.md","filePath":"help-wanted.md"}'),r={name:"help-wanted.md"};function n(l,e,s,d,h,c){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="help-wanted" tabindex="-1">Help wanted <a class="header-anchor" href="#help-wanted" aria-label="Permalink to &quot;Help wanted&quot;">​</a></h1><p><strong>Unverified, please help.</strong> Nothing on this page is advice. These are gaps: facts a reader would want, which we left out of the guide because we could not read them on an official page.</p><p>If you can open the official page, send a <a href="https://github.com/Ifazawezk/living-in-qatar/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">correction</a> with the link. A photo of a counter notice or a screenshot of an app is a helpful lead, but the guide still needs a public official page to cite.</p><h2 id="most-needed" tabindex="-1">Most needed <a class="header-anchor" href="#most-needed" aria-label="Permalink to &quot;Most needed&quot;">​</a></h2><ul><li><strong>Labour law text.</strong> The <a href="./guide/work-and-labour-rights">work page</a> rests on a December 2021 booklet from the National Human Rights Committee, because we could not open the law text or a Ministry of Labour page. Please help us check it against Law No. 14 of 2004 and its later amendments.</li><li><strong>End-of-service gratuity amount.</strong> The booklet gives the amount for domestic workers only. What does the law say for other private-sector workers?</li><li><strong>Current minimum wage.</strong> Is the 2021 figure still correct in 2026?</li><li><strong>Metrash2 basics.</strong> Where is the official download link, and how do you register or activate the app? The Ministry of Interior&#39;s Metrash2 pages did not load for us.</li><li><strong>Licensed exchange houses.</strong> Where does Qatar Central Bank publish the current list, so readers can check a licence?</li><li><strong>Rental law.</strong> Law No. 4 of 2008 and its amendments: who registers a new lease, by when, what it costs, and what the law says about deposits.</li><li><strong>Health card and QID.</strong> News reports say a valid QID replaced the printed health card for residents in April 2026. We could not find this on a Ministry of Public Health, HMC or PHCC page.</li><li><strong>Health insurance for residents.</strong> The official pages we read describe the visitor scheme only. What applies to residents, and who pays?</li></ul><h2 id="arriving-and-residence" tabindex="-1">Arriving and residence <a class="header-anchor" href="#arriving-and-residence" aria-label="Permalink to &quot;Arriving and residence&quot;">​</a></h2><ul><li>Lists of visa-exempt countries, and how long each nationality can stay.</li><li>Hayya fees, stay limits and requirements for each visa type.</li><li>Whether a visitor can extend an on-arrival or Hayya visa.</li><li>What to expect at Hamad International Airport beyond passport, ticket and insurance, including e-gates and customs.</li><li>Who applies for a work visa, and whether both medical tests listed by the Ministry of Interior apply.</li><li>Steps and fee to replace a lost or damaged QID, and the rule on reporting a loss.</li><li>Who still needs an exit permit, and how the exit rules work today.</li><li>Where the residency medical must be done, and what it covers.</li></ul><h2 id="family" tabindex="-1">Family <a class="header-anchor" href="#family" aria-label="Permalink to &quot;Family&quot;">​</a></h2><ul><li>Whether a medical test abroad is still required for family residence. Two Ministry of Interior pages differ.</li><li>The housing salary figure for family residence. Older and newer Ministry of Interior pages differ, and the guide shows both.</li><li>The deadline to apply for residence for a baby born in Qatar.</li><li>Whether a working mother can sponsor her children, or a working wife her husband.</li><li>Attestation rules for marriage and birth certificates issued abroad.</li></ul><h2 id="driving" tabindex="-1">Driving <a class="header-anchor" href="#driving" aria-label="Permalink to &quot;Driving&quot;">​</a></h2><ul><li>Main traffic rules: speed limits, seat belts, phone use, child seats and the points system.</li><li>Fine amounts.</li><li>Which nationalities can convert a foreign licence without a course.</li><li>Whether a resident with a QID can keep driving on an international licence.</li><li>How long a licence is valid for non-Qataris.</li><li>What to do after a serious accident.</li></ul><h2 id="money-and-housing" tabindex="-1">Money and housing <a class="header-anchor" href="#money-and-housing" aria-label="Permalink to &quot;Money and housing&quot;">​</a></h2><ul><li>Whether you must complain to your bank before going to Qatar Central Bank, and how long QCB takes to reply.</li><li>QCB&#39;s consumer protection phone numbers. Two QCB pages list different numbers.</li><li>A current list of what banks need to open an account. The official text we read dates from 2013.</li><li>How to take a case to the Rental Disputes Settlement Committee.</li><li>Kahramaa&#39;s account deposit, and how to close an account when you move out.</li><li>Kahramaa&#39;s tariff rates, in a form that can be quoted.</li><li>Whether Qatar charges VAT.</li><li>A newer consumer price index release than June 2026.</li></ul><h2 id="getting-around-phone-and-emergencies" tabindex="-1">Getting around, phone and emergencies <a class="header-anchor" href="#getting-around-phone-and-emergencies" aria-label="Permalink to &quot;Getting around, phone and emergencies&quot;">​</a></h2><ul><li>Metro and tram fares, Travel Card prices, and where to buy or top up a card.</li><li>Exact metro and tram hours.</li><li>Karwa bus fares, smart cards and the route list.</li><li>Ooredoo home fibre details.</li><li>Whether the Communications Regulatory Authority&#39;s complaint timings from 2019 and 2020 still apply.</li><li>Separate numbers for police, fire and the coast guard, if there are any.</li><li>Emergency numbers for gas leaks, sewage and roads.</li></ul><h2 id="holidays-and-schools" tabindex="-1">Holidays and schools <a class="header-anchor" href="#holidays-and-schools" aria-label="Permalink to &quot;Holidays and schools&quot;">​</a></h2><ul><li>Official list of public holidays, and how each date is announced.</li><li>The rule for the date of National Sport Day, and whether it is one of the employer-set days for private-sector workers.</li><li>Ramadan working hours for 2026 in the private sector and in government.</li><li>The private school complaints form and enrolment guide on the Ministry of Education&#39;s site, which did not load for us.</li></ul><h2 id="sites-we-could-not-read-automatically" tabindex="-1">Sites we could not read automatically <a class="header-anchor" href="#sites-we-could-not-read-automatically" aria-label="Permalink to &quot;Sites we could not read automatically&quot;">​</a></h2><p>Please check these in a normal browser. Some turn away automated visitors, and some did not answer from where we checked in October 2026. That does not mean they are down for you.</p><ul><li>Asked for a bot check or refused the request: hukoomi.gov.qa, gco.gov.qa, mof.gov.qa.</li><li>Did not connect or dropped the connection: mol.gov.qa, qr.com.qa, diwan.gov.qa, cm.gov.qa, dohahamadairport.com.</li><li>Loaded with no readable text: almeezan.qa.</li></ul>',20)])])}const m=a(r,[["render",n]]);export{f as __pageData,m as default};
